CREATE DATABASE IF NOT EXISTS matcha_house; USE matcha_house;
CREATE TABLE IF NOT EXISTS users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,username VARCHAR(50) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,role ENUM('admin','petugas') NOT NULL DEFAULT 'petugas',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS products(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,category VARCHAR(100) NOT NULL DEFAULT 'Classic',price DECIMAL(12,2) NOT NULL DEFAULT 0,stock INT NOT NULL DEFAULT 0,description VARCHAR(255) DEFAULT '',emoji VARCHAR(20) DEFAULT '🍵',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS transactions(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NULL,customer_name VARCHAR(100) NOT NULL DEFAULT 'Customer',phone VARCHAR(30) DEFAULT '',total DECIMAL(12,2) NOT NULL,paid DECIMAL(12,2) NOT NULL,change_amount DECIMAL(12,2) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_t_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS transaction_items(id INT AUTO_INCREMENT PRIMARY KEY,transaction_id INT NOT NULL,product_id INT NULL,product_name VARCHAR(150) NOT NULL,price DECIMAL(12,2) NOT NULL,qty INT NOT NULL,subtotal DECIMAL(12,2) NOT NULL,CONSTRAINT fk_i_t FOREIGN KEY(transaction_id) REFERENCES transactions(id) ON DELETE CASCADE,CONSTRAINT fk_i_p FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE SET NULL);
